"""Deterministic distinct synthetic business objects; used only by guarded serve.py schemas."""
def statements(scale):
    n=131*scale
    def insert(table,columns,rows):
        for offset in range(0,len(rows),200):yield "INSERT INTO "+table+"("+columns+") VALUES "+",".join(rows[offset:offset+200])
    yield from insert("sys_user","user_id,dept_id,user_name,nick_name,password,role,status,is_delete,force_password_change",[f"({5100000+i},920001,'synthetic-admin-{i}','Synthetic concurrent administrator {i}','review-fixture-password','0','1',0,0)" for i in range(30)])
    yield from insert("sys_user","user_id,dept_id,user_name,nick_name,password,role,status,is_delete,force_password_change",[f"({5000000+i},920001,'synthetic-{i}','Synthetic reporter {i}','review-fixture-password','1','1',0,0)" for i in range(n)])
    yield from insert("biz_task","task_id,project_id,parent_id,phase,task_code,task_name,level,dept_id,leader_id,auditor_id,principal_id,data_type,target_value,current_value,progress,status,is_delete",[f"({3000000+i},1,930001,2026,'SYN{i:05d}','Synthetic distinct task {i}',3,{920001+i%2},{5000000+i},910003,910002,'1',10,{i%11},{min(i%11*10,100)},'1',0)" for i in range(n)])
    yield from insert("biz_material_submission","sub_id,task_id,file_id,reported_value,submit_by,submit_dept_id,manage_dept_id,file_suffix,flow_status,current_handler_id,is_delete,submit_time",[f"({7000000+4*i+j},{3000000+i},940001,{j+1},{5000000+i},920001,920001,'pdf',{10 if j==3 else 40},{5100000+i%30 if j==3 else 'NULL'},0,DATE_ADD('2026-09-01',INTERVAL {4*i+j} SECOND))" for i in range(n) for j in range(4)])
    yield from insert("biz_performance","perf_id,project_id,perf_code,perf_name,target_value,current_value,data_type,dept_id,principal_id,auditor_id,leader_id,ancestors",[f"({4000000+i},1,'2.1.synthetic-{i}','Synthetic performance {i}',10,{i%11},'1',920001,910002,910003,{5000000+i},'0,2,2.1')" for i in range(n)])
    yield from insert("biz_performance_year","year_id,perf_id,year,target_value,actual_value",[f"({4100000+i},{4000000+i},2026,10,{i%11})" for i in range(n)])
    yield from insert("biz_performance_submission","sub_id,perf_id,year_id,year,actual_value,submit_by,submit_time,flow_status,current_handler_id,comment,is_delete",[f"({4200000+2*i+j},{4000000+i},{4100000+i},2026,{i%11},{5000000+i},DATE_ADD('2026-09-01',INTERVAL {2*i+j} SECOND),{10 if j else 30},{5100000+i%30 if j else 110228},'Distinct performance report {i}-{j}',0)" for i in range(n) for j in range(2)])
    yield from insert("biz_achievement","ach_id,category,level,ach_name,department,got_time,dept_id,create_by,audit_status,comment,is_competition,is_delete",[f"({4300000+i},1,'Province','Synthetic achievement {i}','Synthetic department','2026-09-01',920001,1910001,{10 if i%2 else 30},'Distinct achievement {i}',0,0)" for i in range(n)])
    yield from insert("biz_achievement_submission","sub_id,ach_id,submit_by,submit_time,flow_status,current_handler_id,is_delete",[f"({4400000+i},{4300000+i},1910001,DATE_ADD('2026-09-01',INTERVAL {i} SECOND),{10 if i%2 else 30},{110228 if i%2 else 'NULL'},0)" for i in range(n)])
    yield from insert("sys_notice","notice_id,from_user_id,to_user_id,type,title,content,source_type,source_id,is_read,is_delete,create_time",[f"({8000000+i},910003,{5100000+(i%30)},'1','Synthetic message {i}','Distinct historical body {i}','x',NULL,'{i%2}',0,DATE_ADD('2026-09-01',INTERVAL {i} SECOND))" for i in range(n*8)])
    yield from insert("biz_work_record","record_id,owner_id,owner_name,record_year,record_month,status,delete_marker,problems,next_focus,other_matters,submit_time,create_time,update_time",[f"({6000000+i},{5000000+i},'Synthetic reporter {i}',2026,9,1,0,'Independent frozen narrative {i}','Next {i}','Other {i}',DATE_ADD('2026-09-01',INTERVAL {i} SECOND),'2026-09-01','2026-09-02')" for i in range(n)])
    yield from insert("biz_work_record_entry","record_id,reform_task_id,reform_task_name,key_progress,stage_results,typical_practices",[f"({6000000+i},930000,'Synthetic reform root','Distinct progress {i}','Distinct result {i}','Practice {i}')" for i in range(n)])
    yield from insert("sys_admin_operation_log","module,action,target_type,target_id,target_name,operator_id,reason,before_json,after_json,create_time",[f"('TASK','UPDATE','TASK','{3000000+i%n}','Synthetic operation {i}',110228,'Synthetic benchmark','{{}}','{{}}',DATE_ADD('2026-09-01',INTERVAL {i} SECOND))" for i in range(n*4)])
    yield "INSERT INTO biz_budget_sheet(sheet_id,year,month) VALUES(4500000,2026,10)"
    yield from insert("biz_budget_import_version","sheet_id,year,month,version_no,operation_type,snapshot_json,created_by,remark,create_time",[f"(4500000,2026,10,{i+1},'IMPORT','{{}}',110228,'Synthetic version {i}',DATE_ADD('2026-09-01',INTERVAL {i} SECOND))" for i in range(n)])
    yield "INSERT INTO biz_performance(perf_id,project_id,perf_code,perf_name,target_value,current_value,data_type,dept_id,principal_id,auditor_id,leader_id,ancestors,is_delete) SELECT 4600000+indicator_id,1,indicator_code,CASE WHEN indicator_id=10 THEN '发布《工程机械产业发展报告》数量' ELSE CONCAT('Synthetic core indicator ',indicator_id) END,100,7,'1',920001,910002,910003,910001,'0,1,1.1',0 FROM biz_core_indicator"
    yield "INSERT INTO biz_performance_year(year_id,perf_id,year,target_value,actual_value) SELECT 4700000+indicator_id,4600000+indicator_id,2026,100,7 FROM biz_core_indicator"
    for j in range(12*scale):
        yield f"INSERT INTO biz_core_report(report_id,indicator_id,record_year,record_month,performance_code,indicator_name,target_value,data_type,previous_year_value,actual_value,submit_by,submit_name,principal_id,archive_handler_id,flow_status,submit_time,archive_time) SELECT 9000000+{j}*10+c.indicator_id,c.indicator_id,2026,{j%10+1},c.indicator_code,p.perf_name,100,'1',0,{j+1},{5000000+j%n},'Synthetic reporter',910002,{5100000+j%30},30,DATE_ADD('2026-10-01',INTERVAL {j} SECOND),DATE_ADD('2026-10-01',INTERVAL {j+1} SECOND) FROM biz_core_indicator c JOIN biz_performance p ON p.perf_id=4600000+c.indicator_id"
    yield "INSERT INTO biz_core_audit_log(report_id,operator_id,action,pre_status,post_status,comment,create_time) SELECT report_id,archive_handler_id,'通过',20,30,'Synthetic archive trace',archive_time FROM biz_core_report WHERE report_id>=9000000"
    yield from insert("biz_budget_source_item","sheet_id,source_key,source_name,display_order,annual_plan",[f"(4500000,'{key}','Synthetic source {key}',{i+1},100)" for i,key in enumerate(('central','province','local','school','other'))])
    yield from insert("biz_budget_task_item","sheet_id,task_index,task_name,amount,goods,capital,other,core_output,target_value,achieved",[f"(4500000,{i},'Synthetic reform {i}',50,10,5,2,'Original imported core text','100','Original imported result')" for i in range(1,11)])
